// Backfills postcode for venues that have lat/lng but no postcode, using
// reverse-geocoded results pre-computed against postcodes.io (774/775
// resolved — see data/_postcode_backfill.json, generated by
// scripts/_precompute_postcode_backfill.mjs). Reading from a pre-computed,
// already-eyeballed cache rather than hitting the external API live during
// the migration, since the API call doesn't need DB access and was already
// validated (spot-checked against known-correct postcodes) ahead of time.
//
// IMPORTANT: run this BEFORE phase2-04-move-wrong-city.mjs — backfilling
// postcodes here surfaces ~160 additional wrong-city venues (on top of the
// 57 found in the original Phase 1 audit) that phase2-04 depends on.
// See reports/data-quality-audit.md §4.2 and the Phase 2 summary.
//
//   node scripts/migrations/phase2-03-backfill-postcodes.mjs [--execute]

import { readFileSync } from 'fs'
import { EXECUTE, getPool, runBatched } from './_lib.mjs'

const backfill = JSON.parse(readFileSync('data/_postcode_backfill.json', 'utf-8')).filter((b) => b.postcode)

console.log(`Found ${backfill.length} venues with a resolved postcode to backfill (of 775 candidates with lat/lng — 1 had no UK postcode within 1km, likely corrupted coordinates, left alone).`)
console.log(EXECUTE ? 'EXECUTING — this will UPDATE postcode.' : 'DRY RUN — no changes will be made.')

const pool = await getPool()
try {
  await runBatched(backfill, async (b) => {
    const client = await pool.connect()
    try {
      const check = await client.query('SELECT id, name, postcode FROM venues WHERE id = $1', [b.id])
      if (check.rows.length === 0) {
        console.log(`  SKIP  id=${b.id} "${b.name}" — no longer in DB`)
        return 'skipped'
      }
      if (check.rows[0].postcode) {
        console.log(`  SKIP  id=${b.id} "${b.name}" — already has a postcode ("${check.rows[0].postcode}") since audit, don't overwrite`)
        return 'skipped'
      }
      console.log(`  ${EXECUTE ? 'UPDATE' : 'would UPDATE'}  id=${b.id} "${b.name}" (${b.townSlug}) -> postcode='${b.postcode}' (reverse-geocoded from lat/lng)`)
      if (EXECUTE) {
        await client.query('UPDATE venues SET postcode = $1 WHERE id = $2', [b.postcode, b.id])
      }
    } finally {
      client.release()
    }
  })
} finally {
  await pool.end()
}
